const PAGE_SIZE = 200;

async function fetchAll<T>(fetchPage: (page: number) => Promise<{ items: T[]; hasMore: boolean }>): Promise<T[]> {
  const all: T[] = [];
  let page = 1;
  for (;;) {
    const res = await fetchPage(page);
    for (const item of res.items) all.push(item);
    if (!res.hasMore) break;
    page += 1;
  }
  return all;
}

function dayOf(iso: string, timeZone: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) {
    throw new AppError('INVALID_DATE', 'Data inválida encontrada em uma tarefa: ' + iso, 500);
  }
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
}

function mondayOf(today: string): string {
  const d = new Date(today + 'T00:00:00Z');
  const offset = (d.getUTCDay() + 6) % 7;
  d.setUTCDate(d.getUTCDate() - offset);
  return d.toISOString().slice(0, 10);
}

