  'tarefas.painel_tarefas.carregarPainelTarefas': async function (input, ctx) {
    // gestorPorAcessoPlataforma: ser gestor vem do acesso da plataforma (papel do actorScope)
    const scope = ctx.sessionContext.actorScope ?? [];
    const isGestor = scope.some((s) => s === 'gestor' || s.endsWith(':gestor'));
    if (!isGestor) {
      throw new AppError('FORBIDDEN', 'Somente o gestor pode ver o painel de tarefas.', 403, { ruleId: 'gestorPorAcessoPlataforma' });
    }

    const timeZone = ctx.organization.timezone ?? 'UTC';
    const today = dayOf(ctx.clock.nowIso(), timeZone);
    const weekStart = mondayOf(today);

    // membroVeResponsavelOuCriador: o gestor vê todas as tarefas, sem filtro de membro
    const tarefas = await fetchAll((page) => listTarefa({ page, pageSize: PAGE_SIZE }, ctx));
    const listasAll = await fetchAll((page) => listListaTarefas({ page, pageSize: PAGE_SIZE }, ctx));

    // tarefaAbertaVencimento: aberta = nem concluída nem cancelada
    const isAberta = (status: string): boolean => status !== 'concluida' && status !== 'cancelada';
    const abertas = tarefas.filter((t) => isAberta(t.status));

    let vencemHoje = 0;
    let atrasadas = 0;
    for (const t of abertas) {
      if (t.prazo == null) continue;
      const prazo = String(t.prazo).slice(0, 10);
      if (prazo === today) vencemHoje += 1;
      else if (prazo < today) atrasadas += 1;
    }

    let devolvidasPendentes = 0;
    for (const t of tarefas) {
      if (t.status !== 'emAndamento') continue;
      const devolvidaEm = t.details.devolvidaEm;
      if (devolvidaEm == null) continue;
      const retomadaEm = t.details.retomadaEm;
      if (retomadaEm == null || Date.parse(retomadaEm) < Date.parse(devolvidaEm)) devolvidasPendentes += 1;
    }

    // itens de checklist das tarefas abertas
    const itensPorTarefa = new Map<string, { total: number; concluidos: number }>();
    await Promise.all(
      abertas.map(async (t) => {
        const itens = await fetchAll((page) => listItemChecklist({ tarefaId: t.id, page, pageSize: PAGE_SIZE }, ctx));
        let concluidos = 0;
        for (const item of itens) {
          if (item.details.concluido === true) concluidos += 1;
        }
        itensPorTarefa.set(t.id, { total: itens.length, concluidos });
      })
    );

    const listas = [...listasAll]
      .sort((a, b) => a.nome.localeCompare(b.nome, 'pt'))
      .map((lista) => {
        const abertasDaLista = abertas.filter((t) => t.listaId === lista.id);
        let itensTotal = 0;
        let itensConcluidos = 0;
        const tarefasComChecklist: Painel_tarefasContracts['tarefas.painel_tarefas.carregarPainelTarefas']['output']['listas'][number]['tarefas'] = [];
        for (const t of abertasDaLista) {
          const c = itensPorTarefa.get(t.id) ?? { total: 0, concluidos: 0 };
          itensTotal += c.total;
          itensConcluidos += c.concluidos;
          if (c.total > 0) {
            tarefasComChecklist.push({
              id: t.id,
              titulo: t.titulo,
              listaId: t.listaId,
              details: { progressoChecklist: c.concluidos + ' de ' + c.total },
            });
          }
        }
        return {
          id: lista.id,
          nome: lista.nome,
          details: { quantidadeTarefasAbertas: abertasDaLista.length },
          itensChecklistConcluidos: itensConcluidos,
          itensChecklistTotal: itensTotal,
          tarefas: tarefasComChecklist,
        };
      });

    // concluídas na semana corrente (segunda-feira até hoje), por responsável
    const contagem = new Map<string, number>();
    for (const t of tarefas) {
      if (t.status !== 'concluida') continue;
      const concluidaEm = t.details.concluidaEm;
      if (concluidaEm == null) continue;
      const dia = dayOf(concluidaEm, timeZone);
      if (dia < weekStart || dia > today) continue;
      contagem.set(t.responsavelId, (contagem.get(t.responsavelId) ?? 0) + 1);
    }

    const concluidasSemana: Painel_tarefasContracts['tarefas.painel_tarefas.carregarPainelTarefas']['output']['concluidasSemana'] = [];
    for (const [responsavelId, quantidade] of contagem) {
      const participante = await getParticipante({ id: responsavelId }, ctx);
      concluidasSemana.push({
        responsavelId,
        participante: { details: { identification: { name: participante.details.identification.name } } },
        quantidadeConcluidas: quantidade,
      });
    }
    concluidasSemana.sort((a, b) => {
      if (b.quantidadeConcluidas !== a.quantidadeConcluidas) return b.quantidadeConcluidas - a.quantidadeConcluidas;
      return a.participante.details.identification.name.localeCompare(b.participante.details.identification.name, 'pt');
    });

    return {
      indicadores: {
        tarefasAbertas: abertas.length,
        vencemHoje,
        atrasadas,
        devolvidasPendentes,
      },
      listas,
      concluidasSemana,
    };
  },
};
